import React, { useState, useEffect } from 'react';
import axios from 'axios';
import './AdminProducts.css';

function AdminProducts() {
  const [products, setProducts] = useState([]);
  const [categories, setCategories] = useState([]);
  const [editingId, setEditingId] = useState(null);
  const [editData, setEditData] = useState({});
  const [editImageFile, setEditImageFile] = useState(null);
  const [message, setMessage] = useState('');
  
  // 🔍 NOVOS ESTADOS PARA BUSCA E FILTRO
  const [searchTerm, setSearchTerm] = useState('');
  const [selectedCategory, setSelectedCategory] = useState('');

  const API_URL = 'http://localhost:3001/api';

  useEffect(() => {
    fetchProducts();
    fetchCategories();
  }, []);

  const fetchProducts = async () => {
    try {
      const response = await axios.get(`${API_URL}/products`);
      setProducts(response.data);
    } catch (error) {
      console.error('Erro ao buscar produtos:', error);
    }
  };

  const fetchCategories = async () => {
    try {
      const response = await axios.get(`${API_URL}/categories`);
      setCategories(response.data);
    } catch (error) {
      console.error('Erro ao buscar categorias:', error);
    }
  };

  // 🔍 FUNÇÃO DE FILTRO
  const filteredProducts = products.filter(product => {
    const matchesSearch = product.name.toLowerCase().includes(searchTerm.toLowerCase());
    const matchesCategory = selectedCategory === '' || product.category_id === parseInt(selectedCategory);
    return matchesSearch && matchesCategory;
  });

  // 📊 ESTATÍSTICAS
  const totalProducts = products.length;
  const lowStockCount = products.filter(p => (p.estoque || 0) > 0 && (p.estoque || 0) <= 10).length;
  const outOfStockCount = products.filter(p => (p.estoque || 0) === 0).length;

  const startEdit = (product) => {
    setEditingId(product.id);
    setEditData({ ...product });
  };

  const saveEdit = async () => {
    try {
      const formData = new FormData();
      formData.append('name', editData.name);
      formData.append('price', parseFloat(editData.price));
      formData.append('unit', editData.unit);
      formData.append('category_id', parseInt(editData.category_id));
      formData.append('estoque', parseInt(editData.estoque) || 0);
      
      if (editImageFile) {
        formData.append('image', editImageFile);
      }

      await axios.put(`${API_URL}/products/${editingId}`, formData, {
        headers: { 'Content-Type': 'multipart/form-data' }
      });
      
      setMessage('✅ Produto atualizado com sucesso!');
      setEditingId(null);
      setEditImageFile(null);
      fetchProducts();
      setTimeout(() => setMessage(''), 3000);
    } catch (error) {
      setMessage('❌ Erro ao atualizar produto');
      console.error(error);
    }
  };

  const deleteProduct = async (id) => {
    if (window.confirm('Tem certeza que deseja deletar este produto?')) {
      try {
        await axios.delete(`${API_URL}/products/${id}`);
        setMessage('✅ Produto deletado com sucesso!');
        fetchProducts();
        setTimeout(() => setMessage(''), 3000);
      } catch (error) {
        setMessage('❌ Erro ao deletar produto');
        console.error(error);
      }
    }
  };

  const getCategoryName = (categoryId) => {
    const cat = categories.find(c => c.id === categoryId);
    return cat ? cat.name : 'N/A';
  };

  const getStockStatus = (estoque) => {
    if (estoque > 10) {
      return { icon: '🟢', label: 'OK', color: '#22c55e' };
    } else if (estoque > 0) {
      return { icon: '🟡', label: 'BAIXO', color: '#f59e0b' };
    } else {
      return { icon: '🔴', label: 'VAZIO', color: '#ef4444' };
    }
  };

  return (
    <div className="admin-products">
      {/* HEADER */}
      <div className="admin-header">
        <h2>📦 Gerenciar Produtos</h2>
        <div className="header-stats">
          <div className="stat">
            <span className="stat-label">Total</span>
            <span className="stat-value">{totalProducts}</span>
          </div>
          <div className="stat warning">
            <span className="stat-label">Baixo Estoque</span>
            <span className="stat-value">{lowStockCount}</span>
          </div>
          <div className="stat danger">
            <span className="stat-label">Fora de Estoque</span>
            <span className="stat-value">{outOfStockCount}</span>
          </div>
        </div>
      </div>

      {/* MENSAGEM DE FEEDBACK */}
      {message && <div className={`admin-message ${message.includes('✅') ? 'success' : 'error'}`}>{message}</div>}

      {/* FILTROS */}
      <div className="filters-section">
        <div className="search-box">
          <input
            type="text"
            placeholder="🔍 Buscar por nome do produto..."
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
            className="search-input"
          />
        </div>

        <div className="category-filter">
          <select 
            value={selectedCategory}
            onChange={(e) => setSelectedCategory(e.target.value)}
            className="category-select"
          >
            <option value="">📁 Todas as categorias</option>
            {categories.map(cat => (
              <option key={cat.id} value={cat.id}>{cat.name}</option>
            ))}
          </select>
        </div>

        <div className="results-info">
          Mostrando <strong>{filteredProducts.length}</strong> de <strong>{totalProducts}</strong> produtos
        </div>
      </div>

      {/* LISTA DE PRODUTOS */}
      <div className="products-container">
        {filteredProducts.length === 0 ? (
          <div className="empty-state">
            <p>📭 Nenhum produto encontrado</p>
            {searchTerm && <p className="subtitle">Tente outro termo de busca</p>}
          </div>
        ) : (
          <div className="products-grid">
            {filteredProducts.map(product => {
              const stockStatus = getStockStatus(product.estoque || 0);
              return (
                <div key={product.id} className="product-card">
                  {editingId === product.id ? (
                    // 🖼️ MODAL DE EDIÇÃO MELHORADO
                    <div className="edit-modal">
                      <div className="modal-header">
                        <div className="modal-product-info">
                          {product.image_url && (
                            <img src={`http://localhost:3001${product.image_url}`} alt={product.name} className="modal-thumbnail" />
                          )}
                          <div>
                            <h3>{product.name}</h3>
                            <p className="modal-category">Categoria: {getCategoryName(product.category_id)}</p>
                          </div>
                        </div>
                        <button className="close-modal" onClick={() => setEditingId(null)}>✕</button>
                      </div>

                      <div className="edit-form">
                        <div className="form-group">
                          <label>Nome do Produto</label>
                          <input
                            type="text"
                            value={editData.name}
                            onChange={(e) => setEditData({...editData, name: e.target.value})}
                            className="form-input"
                          />
                        </div>

                        <div className="form-row">
                          <div className="form-group">
                            <label>Preço (R$)</label>
                            <input
                              type="number"
                              value={editData.price}
                              onChange={(e) => setEditData({...editData, price: e.target.value})}
                              className="form-input"
                              step="0.01"
                            />
                          </div>

                          <div className="form-group">
                            <label>Unidade</label>
                            <input
                              type="text"
                              value={editData.unit}
                              onChange={(e) => setEditData({...editData, unit: e.target.value})}
                              className="form-input"
                            />
                          </div>
                        </div>

                        <div className="form-row">
                          <div className="form-group">
                            <label>Estoque</label>
                            <input
                              type="number"
                              value={editData.estoque || 0}
                              onChange={(e) => setEditData({...editData, estoque: e.target.value})}
                              className="form-input"
                              min="0"
                            />
                          </div>

                          <div className="form-group">
                            <label>Categoria</label>
                            <select
                              value={editData.category_id}
                              onChange={(e) => setEditData({...editData, category_id: e.target.value})}
                              className="form-input"
                            >
                              <option value="">Selecione categoria</option>
                              {categories.map(cat => (
                                <option key={cat.id} value={cat.id}>{cat.name}</option>
                              ))}
                            </select>
                          </div>
                        </div>

                        <div className="form-group">
                          <label>Nova Imagem (opcional)</label>
                          <input
                            type="file"
                            accept="image/*"
                            onChange={(e) => setEditImageFile(e.target.files[0])}
                            className="form-input"
                          />
                          {editImageFile && <p className="file-selected">✅ {editImageFile.name}</p>}
                        </div>

                        <div className="form-buttons">
                          <button onClick={saveEdit} className="btn-save">💾 Salvar Alterações</button>
                          <button onClick={() => setEditingId(null)} className="btn-cancel">❌ Cancelar</button>
                        </div>
                      </div>
                    </div>
                  ) : (
                    // 🎯 CARD DE PRODUTO
                    <div className="product-display">
                      <div className="product-image-wrapper">
                        {product.image_url ? (
                          <img src={`http://localhost:3001${product.image_url}`} alt={product.name} className="product-image" />
                        ) : (
                          <div className="no-image">📸 Sem imagem</div>
                        )}
                      </div>

                      <div className="product-info-card">
                        <h4 className="product-name">{product.name}</h4>
                        <p className="product-category">📁 {getCategoryName(product.category_id)}</p>
                        <p className="product-price">R$ {parseFloat(product.price).toFixed(2)}</p>
                        <p className="product-unit">Unidade: {product.unit}</p>

                        <div className="stock-badge" style={{ color: stockStatus.color, borderColor: stockStatus.color }}>
                          {stockStatus.icon} {stockStatus.label} ({product.estoque || 0})
                        </div>
                      </div>

                      <div className="product-actions-card">
                        <button onClick={() => startEdit(product)} className="btn-edit">✏️ Editar</button>
                        <button onClick={() => deleteProduct(product.id)} className="btn-delete">🗑️ Deletar</button>
                      </div>
                    </div>
                  )}
                </div>
              );
            })}
          </div>
        )}
      </div>
    </div>
  );
}

export default AdminProducts;
